SELECT s.id,s.authors,coalesce((SELECT jsonb_agg(coalesce(u.steam_name,a.id) ORDER BY a.n) FROM unnest(s.authors) WITH ORDINALITY a(id,n) LEFT JOIN public."user" u ON u.steam_id::text=a.id),'[]'::jsonb) AS author_names,s.workshop_id,s.date_created::text AS submitted_at,s.state,s.revision,((s.next_inspection_at<=now()) OR (r.submission_end<=now() AND s.retry_category IS NULL AND (v.id IS NULL OR v.date_created<r.submission_end))) AS inspection_due,(r.submission_end<=now() AND (v.id IS NULL OR v.date_created<r.submission_end)) AS final_scan_due,s.latest_validation_id FROM zc_private.level_submissions s JOIN zc_private.level_submission_contest c ON c.id=s.id_contest JOIN public.zsl_round r ON r.id=c.id_zsl_round LEFT JOIN zc_private.level_submission_validation v ON v.id=s.latest_validation_id WHERE s.id_contest=$1 AND s.state='selected' ORDER BY s.date_created,s.id
